"""__DISPLAY_NAME__, generated by `plexi plugin init`.

Plexi calls init(size, args) once, update(event) for every event, and view()
to draw. update() returns effects and view() only reads state.

Guide: sdk/python/AUTHORING.md in the Plexi repo.
API reference: https://plexiapp.com/docs/sdk
"""

from plexi_sdk import log, state
from plexi_sdk.effects import SetState, SetTitle
from plexi_sdk.events import KeyEvent, Resize, UiAction
from plexi_sdk.ui import Button, Column, FooterKeys, SurfaceHeader, Text

# Below this pane width the view drops its hint line.
COMPACT_WIDTH = 360


def init(size, args):
    width, height = size
    log.info(f"__DISPLAY_NAME__: init {width:.0f}x{height:.0f}")
    return [
        SetTitle("__DISPLAY_NAME__"),
        SetState({"width": width, "height": height}),
    ]


def update(event):
    if isinstance(event, Resize):
        return [SetState({"width": event.width, "height": event.height})]
    if isinstance(event, UiAction) and event.handler_id == "increment":
        return [_add_one()]
    if isinstance(event, KeyEvent) and event.pressed and event.key == "+":
        return [_add_one()]
    return []


def _add_one() -> SetState:
    count = state.get("count", 0) + 1
    log.info(f"__DISPLAY_NAME__: count={count}")
    return SetState({"count": count})


def view():
    width = state.get("width", 0)
    # A width of 0 means the host has not reported a size yet.
    compact = 0 < width < COMPACT_WIDTH
    body = [
        Text(str(state.get("count", 0)), bold=True),
        Button("Add one", on_click="increment"),
    ]
    if not compact:
        body.append(Text("Click the button or press +.", color="muted"))
    return Column(
        [
            SurfaceHeader("__DISPLAY_NAME__"),
            *body,
            FooterKeys([("+", "add one")]),
        ],
        grow=True,
    )
